type Engine struct {
	Stores   Stores
	Pipeline []pipeline.Enricher

	GitterHost        string
	GitterClient      *http.Client
	NotifyPyPI        bool
	EcosystemProvider *ecosystem.Provider
}

func (e *Engine) RunTask(ctx context.Context, task Task) error {
	switch task.Type {
	case TaskDelete:
		return e.handleDelete(ctx, task)
	case TaskUpdate:
		return e.handleUpdate(ctx, task)
	default:
		return fmt.Errorf("unknown task type: %v", task.Type)
	}
}

func (e *Engine) handleUpdate(ctx context.Context, task Task) error {
	var gitterClient gitter.Client
	if e.GitterHost != "" {
		var err error
		gitterClient, err = gitter.NewClient(e.GitterHost, e.GitterClient)
		if err != nil {
			logger.WarnContext(ctx, "Failed to create gitter client", slog.Any("error", err))
		}
	}

	params := pipeline.EnrichParams{
		PathInSource:      task.PathInSource,
		EcosystemProvider: e.EcosystemProvider,
		RelationsStore:    e.Stores.Relations,
		GitterClient:      gitterClient,
	}
	var err error
	params.SourceRepo, err = e.Stores.SourceRepo.Get(ctx, task.SourceID)
	if err != nil {
		metrics.RecordWorkerFailedTask(metrics.WorkerErrorSourceRepo, true)
		return err
	}
	if task.Vuln == nil {
		metrics.RecordWorkerFailedTask(metrics.WorkerErrorParse, false)
		return errors.New("vuln not provided")
	}

	// Get the current state of the vuln to check against
	current, err := e.Stores.Vulnerability.GetFull(ctx, task.Vuln.GetId())
	if err == nil {
		params.ExistingVuln = current
	} else if !errors.Is(err, models.ErrNotFound) {
		logger.ErrorContext(ctx, "Failed to get current vuln state", slog.String("vuln_id", task.Vuln.GetId()), slog.Any("error", err))
		metrics.RecordWorkerFailedTask(metrics.WorkerErrorDatastoreGet, true)

		return fmt.Errorf("failed to get current vuln state: %w", err)
	}

	enriched := proto.Clone(task.Vuln).(*osvschema.Vulnerability)
	for _, enricher := range e.Pipeline {
		if err := enricher.Enrich(ctx, enriched, &params); err != nil {
			logger.ErrorContext(ctx, "Enricher failed with error",
				slog.String("id", enriched.GetId()),
				slog.String("enricher", fmt.Sprintf("%T", enricher)),
				slog.Any("error", err),
			)
			metrics.RecordWorkerFailedTask(metrics.WorkerErrorEnrich, true)

			return err
		}
	}

	commits, err := e.populateAffectedCommitsAndTags(ctx, enriched, params.SourceRepo)
	if err != nil {
		logger.ErrorContext(ctx, "Populate affected commits failed", slog.String("id", enriched.GetId()), slog.Any("error", err))
		metrics.RecordWorkerFailedTask(metrics.WorkerErrorCommitEnum, true)

		return err
	}

	if params.ExistingVuln == nil || e.isSemanticallyDifferent(current, enriched) {
		enriched.Modified = timestamppb.Now()
	} else if current.GetModified().AsTime().After(enriched.GetModified().AsTime()) {
		enriched.Modified = current.GetModified()
	}

	// Ensure Modified is at least as new as Withdrawn
	if enriched.GetWithdrawn() != nil && enriched.GetWithdrawn().AsTime().After(enriched.GetModified().AsTime()) {
		enriched.Modified = enriched.GetWithdrawn()
	}

	var rawSHA256 []byte
	if task.SHA256 != "" {
		if decoded, err := hex.DecodeString(task.SHA256); err == nil {
			rawSHA256 = decoded
		}
	}

	if err := e.Stores.Vulnerability.Write(ctx, models.WriteRequest{
		ID:              enriched.GetId(),
		Source:          task.SourceID,
		Path:            task.PathInSource,
		Raw:             task.Vuln,
		RawJSON:         task.RawJSON,
		RawSHA256:       rawSHA256,
		FetchedAt:       task.ReceivedTime,
		GitCommitHash:   task.GitCommitHash,
		GCSGeneration:   task.GCSGeneration,
		Enriched:        enriched,
		AffectedCommits: commits,
	}); err != nil {
		metrics.RecordWorkerFailedTask(metrics.WorkerErrorWrite, true)
		return err
	}

	if e.NotifyPyPI {
		e.notifyPyPI(ctx, enriched, current)
	}

	// Remove ImportFindings
	if e.Stores.ImportFindings != nil {
		if err := e.Stores.ImportFindings.Clear(ctx, enriched.GetId()); err != nil {
			// Don't really want to return an error here since we successfully wrote the vuln
			logger.ErrorContext(ctx, "Failed to clear import findings", slog.String("vuln_id", enriched.GetId()), slog.Any("error", err))
		}
	}

	return nil
}

// semanticallyIgnoredFields are the top-level Vulnerability fields that are not
// considered when deciding whether a vulnerability has changed.
var semanticallyIgnoredFields = []protoreflect.Name{"modified", "published", "schema_version"}

// isSemanticallyDifferent reports whether the two vulnerabilities differ in any
// field other than semanticallyIgnoredFields.
//
// This intentionally uses proto.Equal rather than go-cmp with protocmp.Transform:
// protocmp converts every message into nested maps, which for large records
// (e.g. Ubuntu kernel USNs with big database_specific Structs) allocated
// gigabytes and took tens of seconds per comparison, causing worker OOMs.
func (e *Engine) isSemanticallyDifferent(vuln1, vuln2 *osvschema.Vulnerability) bool {
	return !proto.Equal(withoutSemanticallyIgnoredFields(vuln1), withoutSemanticallyIgnoredFields(vuln2))
}

// withoutSemanticallyIgnoredFields returns a shallow copy of vuln with the
// semanticallyIgnoredFields cleared. Nested messages and lists are shared with
// vuln rather than copied, so the result must only be read, never modified.
func withoutSemanticallyIgnoredFields(vuln *osvschema.Vulnerability) *osvschema.Vulnerability {
	if vuln == nil {
		return nil
	}
	src := vuln.ProtoReflect()
	dst := (&osvschema.Vulnerability{}).ProtoReflect()
	src.Range(func(fd protoreflect.FieldDescriptor, v protoreflect.Value) bool {
		if !slices.Contains(semanticallyIgnoredFields, fd.Name()) {
			dst.Set(fd, v)
		}

		return true
	})
	dst.SetUnknown(src.GetUnknown())

	return dst.Interface().(*osvschema.Vulnerability)
}

func (e *Engine) handleDelete(ctx context.Context, task Task) error {
	id := idFromPath(task.PathInSource)

	// Fetch the 'Last Known Good' state from the DB
	existing, ref, err := e.Stores.Vulnerability.GetWithMetadata(ctx, id)
	if errors.Is(err, models.ErrNotFound) {
		logger.WarnContext(ctx, "Requested deletion for non-existent record",
			slog.String("id", id),
			slog.String("path", task.PathInSource),
			slog.String("source", task.SourceID))

		return nil // Nothing to do
	}
	if err != nil {
		metrics.RecordWorkerFailedTask(metrics.WorkerErrorDelete, true)
		return err
	}

	// Safety Check: Does the record in the DB still belong to this path?
	if ref.Path != task.PathInSource {
		logger.WarnContext(ctx, "Skipping deletion: record moved",
			slog.String("id", id),
			slog.String("current_path", ref.Path),
			slog.String("requested_path", task.PathInSource))

		return nil
	}

	// Already withdrawn?
	if existing.GetWithdrawn() != nil {
		logger.InfoContext(ctx, "Vulnerability already withdrawn, skipping deletion", slog.String("id", id))

		return nil
	}

	// Set the withdrawn + modified dates
	withdrawn := proto.Clone(existing).(*osvschema.Vulnerability)
	withdrawn.Withdrawn = timestamppb.Now()
	withdrawn.Modified = timestamppb.Now()

	// Save the new "Withdrawn" state
	if err := e.Stores.Vulnerability.Write(ctx, models.WriteRequest{
		ID:       id,
		Source:   task.SourceID,
		Path:     task.PathInSource,
		Enriched: withdrawn,
		// When deleting, we clear the commit index
		AffectedCommits: models.AffectedCommitsResult{Skip: false, Commits: nil},
	}); err != nil {
		metrics.RecordWorkerFailedTask(metrics.WorkerErrorDelete, true)
		return err
	}

	// Notify PyPI
	if e.NotifyPyPI {
		e.notifyPyPI(ctx, withdrawn, existing)
	}

	return nil
}

// notifyPyPI publishes a message to a Pub/Sub topic.
// Note that this does not directly notify PyPI; a Cloud Run function
// consumes from this topic to handle the actual notification.
func (e *Engine) notifyPyPI(ctx context.Context, vuln, old *osvschema.Vulnerability) {
	if e.Stores.PyPIPublisher == nil {
	if e.Stores.PyPIPublisher == nil {
		return
	}

	newHasPyPI := false
	for _, affected := range vuln.GetAffected() {
		if affected.GetPackage().GetEcosystem() == "PyPI" {
			newHasPyPI = true
			break
		}
	}

	oldHasPyPI := false
	if old != nil {
		for _, affected := range old.GetAffected() {
			if affected.GetPackage().GetEcosystem() == "PyPI" {
				oldHasPyPI = true
				break
			}
		}
	}

	// If neither has PyPI, nothing to do.
	if !newHasPyPI && !oldHasPyPI {
		return
	}

	toNotify := vuln
	// If it was removed from PyPI, we need to notify with a withdrawn date to trigger a deletion in the bridge.
	if oldHasPyPI && !newHasPyPI {
		toNotify = proto.Clone(vuln).(*osvschema.Vulnerability)
		toNotify.Withdrawn = timestamppb.Now()
		// Copy over the PyPI affected ranges from the old vuln so the bridge knows which project to withdraw.
		for _, affected := range old.GetAffected() {
			if affected.GetPackage().GetEcosystem() == "PyPI" {
				toNotify.Affected = append(toNotify.Affected, proto.Clone(affected).(*osvschema.Affected))
			}
		}
	}

	data, err := protojson.Marshal(toNotify)
	if err != nil {
		logger.ErrorContext(ctx, "Failed to marshal vuln for PyPI notification", slog.String("id", vuln.GetId()), slog.Any("error", err))
		return
	}

	res := e.Stores.PyPIPublisher.Publish(ctx, &pubsub.Message{
		Data: data,
	})

	_, err = res.Get(ctx)
	if err != nil {
		logger.ErrorContext(ctx, "Failed to publish PyPI notification", slog.String("id", vuln.GetId()), slog.Any("error", err))
	} else {
		logger.InfoContext(ctx, "Published PyPI notification", slog.String("id", vuln.GetId()))
	}
}

func idFromPath(p string) string {
	return strings.TrimSuffix(path.Base(p), path.Ext(p))
}
package worker

import (
	"cmp"
	"context"
	"fmt"
	"log/slog"
	"strconv"
	"time"

	"cloud.google.com/go/pubsub/v2"
	"github.com/google/osv.dev/go/internal/metrics"
	"github.com/google/osv.dev/go/logger"
	"github.com/klauspost/compress/zstd"
	"github.com/ossf/osv-schema/bindings/go/osvschema"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/propagation"
	"google.golang.org/protobuf/encoding/protojson"
	"google.golang.org/protobuf/proto"
)

const defaultMaxDecodedPayloadBytes = 128 << 20 // 128 MiB

var defaultZstdDecoder = newZstdDecoder(defaultMaxDecodedPayloadBytes)

func newZstdDecoder(maxMemory uint64) *zstd.Decoder {
	dec, err := zstd.NewReader(nil, zstd.WithDecoderMaxMemory(maxMemory))
	if err != nil {
		panic(fmt.Sprintf("failed to initialize zstd decoder: %v", err))
	}

	return dec
}

type Subscriber struct {
	Engine      Engine
	PubSubSub   *pubsub.Subscriber
	zstdDecoder *zstd.Decoder // defaults to defaultZstdDecoder when nil
}

func (s *Subscriber) Run(ctx context.Context) error {
	return s.PubSubSub.Receive(ctx, s.handleMessage)
}

func (s *Subscriber) handleMessage(ctx context.Context, m *pubsub.Message) {
	start := time.Now()
	defer func() {
		metrics.RecordWorkerLatency(time.Since(start))
	}()

	workPool := m.Attributes["work_pool"]
	if workPool == "" {
		workPool = "default"
	}

	if taskType := m.Attributes["type"]; taskType != "update" {
		logger.InfoContext(ctx, "Skipping message, not an update", slog.Any("task_type", taskType))
		metrics.RecordWorkerTask(metrics.TaskStatusSkipped, metrics.TaskActionUnknown, workPool)
		m.Ack()

		return
	}

	taskCtx := otel.GetTextMapPropagator().Extract(ctx, propagation.MapCarrier(m.Attributes))
	taskCtx, span := otel.Tracer("worker").Start(taskCtx, "process_message")
	defer span.End()
	task := Task{
		SourceID:     m.Attributes["source"],
		PathInSource: m.Attributes["path"],
	}

	logInfo := []any{
		slog.String("source", task.SourceID),
		slog.String("path", task.PathInSource),
	}

	var err error
	task.Vuln, task.RawJSON, err = s.parseVuln(m)
	if err != nil {
		logger.ErrorContext(taskCtx, "Failed to parse vulnerability", append(logInfo, slog.Any("error", err))...)
		metrics.RecordWorkerTask(metrics.TaskStatusError, metrics.TaskActionUnknown, workPool)
		metrics.RecordWorkerFailedTask(metrics.WorkerErrorParse, false)
		m.Nack()

		return
	}

	deleted, err := strconv.ParseBool(m.Attributes["deleted"])
	if err != nil {
		logger.ErrorContext(taskCtx, "Failed to parse deleted attribute, defaulting to false", append(logInfo, slog.Any("error", err))...)
		deleted = false
	}
	action := metrics.TaskActionUpdate
	if deleted {
		task.Type = TaskDelete
		action = metrics.TaskActionDelete
	} else {
		task.Type = TaskUpdate
	}

	task.ReceivedTime, err = s.timeFromUnixSeconds(m.Attributes["req_timestamp"])
	if err != nil {
		logger.ErrorContext(taskCtx, "Failed to parse req_timestamp attribute, ignoring", append(logInfo, slog.Any("error", err))...)
	}
	srcTime := m.Attributes["src_timestamp"]
	if srcTime != "" {
		task.SourceTime, err = s.timeFromUnixSeconds(srcTime)
		if err != nil {
			logger.ErrorContext(taskCtx, "Failed to parse src_timestamp attribute, ignoring", append(logInfo, slog.Any("error", err))...)
		}
	}

	task.SHA256 = m.Attributes["original_sha256"]
	task.GitCommitHash = m.Attributes["git_commit"]
	if genStr := m.Attributes["gcs_generation"]; genStr != "" {
		if gen, err := strconv.ParseInt(genStr, 10, 64); err == nil {
			task.GCSGeneration = &gen
		} else {
			logger.ErrorContext(taskCtx, "Failed to parse gcs_generation attribute, ignoring", append(logInfo, slog.Any("error", err))...)
		}
	}

	if err := s.Engine.RunTask(taskCtx, task); err != nil {
		metrics.RecordWorkerTask(metrics.TaskStatusError, action, workPool)
		logger.ErrorContext(taskCtx, "Failed to process task", append(logInfo, slog.Any("error", err))...)
		m.Nack()
	} else {
		metrics.RecordWorkerTask(metrics.TaskStatusSuccess, action, workPool)
		if deleted {
			metrics.RecordUpstreamWithdrawal(task.SourceID)
		} else if workPool != "reimport" {
			metrics.RecordSourceRecordDiscovered(task.SourceID)
		}
		logTaskLatency(taskCtx, task, workPool)
		m.Ack()
	}
}

func (s *Subscriber) parseVuln(m *pubsub.Message) (*osvschema.Vulnerability, []byte, error) {
	if len(m.Data) == 0 {
		return nil, nil, nil
	}
	var data []byte
	switch m.Attributes["content_encoding"] {
	case "":
		data = m.Data
	case "zstd":
		var err error
		data, err = cmp.Or(s.zstdDecoder, defaultZstdDecoder).DecodeAll(m.Data, nil)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to decompress vulnerability: %w", err)
		}
	default:
		return nil, nil, fmt.Errorf("unrecognized content encoding: %s", m.Attributes["content_encoding"])
	}

	v := &osvschema.Vulnerability{}
	if m.Attributes["format"] == "json" {
		unmarshaler := protojson.UnmarshalOptions{DiscardUnknown: true}
		if err := unmarshaler.Unmarshal(data, v); err != nil {
			return nil, nil, fmt.Errorf("failed to unmarshal JSON vulnerability: %w", err)
		}

		return v, data, nil
	}

	if err := proto.Unmarshal(data, v); err != nil {
		return nil, nil, fmt.Errorf("failed to unmarshal vulnerability: %w", err)
	}

	return v, nil, nil
}

func (s *Subscriber) timeFromUnixSeconds(tsString string) (*time.Time, error) {
	timestamp, err := strconv.ParseInt(tsString, 10, 64)
	if err != nil {
		return nil, err
	}
	ts := time.Unix(timestamp, 0)

	return &ts, nil
}

func logTaskLatency(ctx context.Context, task Task, workPool string) {
	if task.ReceivedTime == nil {
		return
	}
	now := time.Now()
	latency := now.Sub(*task.ReceivedTime)
	latencySeconds := int64(latency.Seconds())
	if workPool != "reimport" {
		metrics.RecordImporterToAvailableLag(task.SourceID, latency)
	}
	logAttrs := []any{
		slog.Int64("latency", latencySeconds),
		slog.String("source", task.SourceID),
		slog.String("path", task.PathInSource),
	}
	if task.SourceTime != nil {
		srcLatency := now.Sub(*task.SourceTime)
		logAttrs = append(logAttrs, slog.Int64("src_latency", int64(srcLatency.Seconds())))
	}
	logger.InfoContext(ctx, fmt.Sprintf("Task update (source_id=%s) latency %d", task.SourceID, latencySeconds), logAttrs...)
}

