// Package models contains the domain types for the OSV database.
package models

import "errors"

// ErrNotFound indicates that a requested entity was not found.
var ErrNotFound = errors.New("not found")

// ErrInvalidArgument indicates that an argument provided to a function or method is invalid.
var ErrInvalidArgument = errors.New("invalid argument")
package models

import (
	"context"
	"errors"
	"iter"
	"time"

	"github.com/ossf/osv-schema/bindings/go/osvschema"
)

// VulnSourceRef represents a minimal vulnerability entry for indexing/reconciliation.
type VulnSourceRef struct {
	ID          string
	Source      string
	Path        string
	ModifiedRaw time.Time
}

// Package represents an affected package or Git repository reference.
type Package struct {
	Package *osvschema.Package
	Repo    string
}

// WriteRequest bundles everything needed to perform a permanent update to an OSV record.
type WriteRequest struct {
	ID              string
	Source          string                   // The source name (e.g. "debian")
