// Package postgres implements the PostgreSQL database store for OSV.
package postgres

import (
	"encoding/json"
	"net/url"
	"slices"
	"strings"

	"github.com/google/osv.dev/go/internal/osvutil"
	"github.com/google/osv.dev/go/osv/ecosystem"
	"github.com/ossf/osv-schema/bindings/go/osvschema"
)

const (
	MinCoarseVersion = "00:00000000.00000000.00000000"
	MaxCoarseVersion = "99:99999999.99999999.99999999"
)

type AffectedEvent struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

type AffectedVersionRow struct {
	VulnID        string
	Name          string
	BaseEcosystem string
	Ecosystems    []string
	CoarseMin     string
	CoarseMax     string
	Versions      []string
	EventsJSON    []byte
}

func affectedVersionSortKey(vulnID, name, baseEcosystem string, ecosystems []string, coarseMin, coarseMax string, versions []string, eventsJSON []byte) string {
	var b strings.Builder
	b.WriteString(vulnID)
	b.WriteString("\x1f")
	b.WriteString(name)
	b.WriteString("\x1f")
	b.WriteString(baseEcosystem)
	b.WriteString("\x1f")
	b.WriteString(strings.Join(ecosystems, "\x1e"))
	b.WriteString("\x1f")
	b.WriteString(coarseMin)
	b.WriteString("\x1f")
	b.WriteString(coarseMax)
	b.WriteString("\x1f")
	if versions == nil {
		b.WriteString("\x00")
	} else {
		sortedVersions := slices.Clone(versions)
		slices.Sort(sortedVersions)
		b.WriteString(strings.Join(sortedVersions, "\x1e"))
	}
	b.WriteString("\x1f")
	if len(eventsJSON) > 0 {
		var events []AffectedEvent
		if err := json.Unmarshal(eventsJSON, &events); err == nil {
			for _, e := range events {
				b.WriteString(e.Type)
				b.WriteString(":")
				b.WriteString(e.Value)
				b.WriteString("\x1e")
			}
		} else {
			b.Write(eventsJSON)
		}
	}

	return b.String()
}

func (av AffectedVersionRow) sortKey() string {
	return affectedVersionSortKey(av.VulnID, av.Name, av.BaseEcosystem, av.Ecosystems, av.CoarseMin, av.CoarseMax, av.Versions, av.EventsJSON)
}

func (av AffectedVersion) sortKey() string {
	return affectedVersionSortKey(av.VulnID, av.Name, av.BaseEcosystem, av.Ecosystems, av.CoarseMin, av.CoarseMax, av.Versions, av.Events)
}

var ubuntuReplacer = strings.NewReplacer(":Pro", "", ":LTS", "")

func removeVariants(eco string) string {
	if strings.HasPrefix(eco, "Ubuntu") {
		return ubuntuReplacer.Replace(eco)
	}

	return ""
}

func normalizeRepo(repoURL string) string {
	// Normalize the repo_url for use with GIT AffectedVersions entities.
	// Lowercases the URL and removes the scheme/protocol, the .git extension, and trailing slashes.
	if repoURL == "" {
		return ""
	}
	parsed, err := url.Parse(repoURL)
	if err != nil {
		return repoURL
	}
	normalized := parsed.Host + parsed.Path
	// Always make the repo lowercase. Major git hosts (e.g. GitHub, GitLab) are
	// already case-insensitive, and even on case-sensitive hosts it is unlikely
	// our data has two distinct repos differing only by case.
	normalized = strings.ToLower(normalized)
	normalized = strings.TrimRight(normalized, "/")
	normalized = strings.TrimSuffix(normalized, ".git")

	return normalized
}

// ComputeAffectedVersions computes the affected_versions rows for a vulnerability.
func ComputeAffectedVersions(vuln *osvschema.Vulnerability) ([]AffectedVersionRow, error) {
	if vuln.GetWithdrawn() != nil {
		return nil, nil
	}

	var res []AffectedVersionRow

	for _, affected := range vuln.GetAffected() {
		var allPkgEcosystems []string
		var baseEcosystem string
		pkgEcosystem := affected.GetPackage().GetEcosystem()
		if pkgEcosystem != "" {
			allPkgEcosystems = []string{pkgEcosystem}
			baseEcosystem, _, _ = strings.Cut(pkgEcosystem, ":")
			if baseEcosystem != pkgEcosystem {
				allPkgEcosystems = append(allPkgEcosystems, baseEcosystem)
			}
			if v := removeVariants(pkgEcosystem); v != "" {
				allPkgEcosystems = append(allPkgEcosystems, v)
			}

			slices.Sort(allPkgEcosystems)
			allPkgEcosystems = slices.Compact(allPkgEcosystems)
		}

		pkgName := affected.GetPackage().GetName()
		eHelper, exists := ecosystem.DefaultProvider.Get(pkgEcosystem)
		if exists {
			pkgName = ecosystem.NormalizePackageName(eHelper, pkgName)
		}
		pkgStart := len(res)

		var gitRepos []string
		hasAffected := false

		for _, r := range affected.GetRanges() {
