func (s *VulnerabilityStore) Write(ctx context.Context, req models.WriteRequest) error {
	// Updates the base records (Vulnerability, ListedVulnerability, AffectedVersions)
	// in a single atomic Datastore transaction. Does not write to GCS.
	if err := s.writeBaseEntities(ctx, req); err != nil {
		return err
	}

	if !req.AffectedCommits.Skip {
		if err := s.updateAffectedCommits(ctx, req.ID, req.AffectedCommits.Commits); err != nil {
			return err
		}
	}

	return s.uploadToGCS(ctx, req.ID, req.Enriched)
}

func (s *VulnerabilityStore) Mutate(ctx context.Context, id string, mutateFn models.MutateFunc) (bool, error) {
	const maxRetries = 3
	path := fmt.Sprintf("all/pb/%s.pb", id)
	dsVulnKey := datastore.NameKey("Vulnerability", id, nil)

	for attempt := range maxRetries {
		attrs, err := s.gcsStore.ReadObjectAttrs(ctx, path)
		if err != nil {
			if errors.Is(err, clients.ErrNotFound) {
				return false, models.ErrNotFound
			}

			return false, fmt.Errorf("failed to read GCS object attrs for %s: %w", id, err)
		}

		data, err := s.gcsStore.ReadObject(ctx, path)
		if err != nil {
			if errors.Is(err, clients.ErrNotFound) {
				return false, models.ErrNotFound
			}

			return false, fmt.Errorf("failed to read GCS object for %s: %w", id, err)
		}

		v := &osvschema.Vulnerability{}
		if err := proto.Unmarshal(data, v); err != nil {
			return false, fmt.Errorf("failed to unmarshal vulnerability %s: %w", id, err)
		}

		oldWithdrawn := v.GetWithdrawn() != nil
		oldListed := NewListedVulnerabilityFromProto(v)

		modified, err := mutateFn(v)
		if err != nil {
			return false, err
		}
		if !modified {
			return false, nil
		}

		dsVuln := new(Vulnerability)
		if err := s.client.Get(ctx, dsVulnKey, dsVuln); err != nil {
			if errors.Is(err, datastore.ErrNoSuchEntity) {
				return false, models.ErrNotFound
			}

			return false, fmt.Errorf("failed to get Vulnerability %s from Datastore: %w", id, err)
		}

		newData, err := proto.Marshal(v)
		if err != nil {
			return false, fmt.Errorf("failed to marshal mutated vulnerability %s: %w", id, err)
		}

		customTime := v.GetModified().AsTime()
		opts := &clients.WriteOptions{
			IfGenerationMatches: &attrs.Generation,
			CustomTime:          &customTime,
			ContentType:         "application/octet-stream",
		}
		if err := s.gcsStore.WriteObject(ctx, path, newData, opts); err != nil {
			if errors.Is(err, clients.ErrPreconditionFailed) && attempt < maxRetries-1 {
				continue
			}

			return false, fmt.Errorf("failed to write mutated vulnerability %s to GCS: %w", id, err)
		}

		isWithdrawn := v.GetWithdrawn() != nil
		newListed := NewListedVulnerabilityFromProto(v)
		updateListed := isWithdrawn != oldWithdrawn || !oldListed.equal(newListed)

		_, err = s.client.RunInTransaction(ctx, func(tx *datastore.Transaction) error {
			var txVuln Vulnerability
			if err := tx.Get(dsVulnKey, &txVuln); err != nil {
				if errors.Is(err, datastore.ErrNoSuchEntity) {
					return models.ErrNotFound
				}

				return err
			}
			txVuln.Modified = customTime
			txVuln.IsWithdrawn = isWithdrawn
			if _, err := tx.Put(dsVulnKey, &txVuln); err != nil {
				return err
			}

			if updateListed {
				listedKey := datastore.NameKey("ListedVulnerability", id, nil)
				if isWithdrawn {
					if err := tx.Delete(listedKey); err != nil && !errors.Is(err, datastore.ErrNoSuchEntity) {
						return err
					}
				} else {
					if _, err := tx.Put(listedKey, newListed); err != nil {
						return err
					}
				}
			}

			return nil
		})
		if err != nil {
			return false, fmt.Errorf("failed to update Datastore entities for %s: %w", id, err)
		}

		return true, nil
	}

