func (s *VulnerabilityStore) Write(ctx context.Context, req models.WriteRequest) error {
	// Updates the base records (Vulnerability, ListedVulnerability, AffectedVersions)
	// in a single atomic Datastore transaction. Does not write to GCS.
	if err := s.writeBaseEntities(ctx, req); err != nil {
		return err
	}

	if !req.AffectedCommits.Skip {
		if err := s.updateAffectedCommits(ctx, req.ID, req.AffectedCommits.Commits); err != nil {
			return err
		}
	}

	return s.uploadToGCS(ctx, req.ID, req.Enriched)
}

func (s *VulnerabilityStore) Mutate(ctx context.Context, id string, mutateFn models.MutateFunc) (bool, error) {
	const maxRetries = 3
	path := fmt.Sprintf("all/pb/%s.pb", id)
	dsVulnKey := datastore.NameKey("Vulnerability", id, nil)

	for attempt := range maxRetries {
		attrs, err := s.gcsStore.ReadObjectAttrs(ctx, path)
		if err != nil {
			if errors.Is(err, clients.ErrNotFound) {
				return false, models.ErrNotFound
			}

			return false, fmt.Errorf("failed to read GCS object attrs for %s: %w", id, err)
		}

		data, err := s.gcsStore.ReadObject(ctx, path)
		if err != nil {
			if errors.Is(err, clients.ErrNotFound) {
				return false, models.ErrNotFound
			}

			return false, fmt.Errorf("failed to read GCS object for %s: %w", id, err)
		}

		v := &osvschema.Vulnerability{}
		if err := proto.Unmarshal(data, v); err != nil {
			return false, fmt.Errorf("failed to unmarshal vulnerability %s: %w", id, err)
		}

		oldWithdrawn := v.GetWithdrawn() != nil
		oldListed := NewListedVulnerabilityFromProto(v)

		modified, err := mutateFn(v)
		if err != nil {
			return false, err
		}
		if !modified {
			return false, nil
		}

		dsVuln := new(Vulnerability)
		if err := s.client.Get(ctx, dsVulnKey, dsVuln); err != nil {
			if errors.Is(err, datastore.ErrNoSuchEntity) {
				return false, models.ErrNotFound
			}

			return false, fmt.Errorf("failed to get Vulnerability %s from Datastore: %w", id, err)
		}

		newData, err := proto.Marshal(v)
		if err != nil {
			return false, fmt.Errorf("failed to marshal mutated vulnerability %s: %w", id, err)
		}

		customTime := v.GetModified().AsTime()
		opts := &clients.WriteOptions{
			IfGenerationMatches: &attrs.Generation,
			CustomTime:          &customTime,
			ContentType:         "application/octet-stream",
		}
		if err := s.gcsStore.WriteObject(ctx, path, newData, opts); err != nil {
			if errors.Is(err, clients.ErrPreconditionFailed) && attempt < maxRetries-1 {
				continue
			}

			return false, fmt.Errorf("failed to write mutated vulnerability %s to GCS: %w", id, err)
		}

		isWithdrawn := v.GetWithdrawn() != nil
		newListed := NewListedVulnerabilityFromProto(v)
		updateListed := isWithdrawn != oldWithdrawn || !oldListed.equal(newListed)

		_, err = s.client.RunInTransaction(ctx, func(tx *datastore.Transaction) error {
			var txVuln Vulnerability
			if err := tx.Get(dsVulnKey, &txVuln); err != nil {
				if errors.Is(err, datastore.ErrNoSuchEntity) {
					return models.ErrNotFound
				}

				return err
			}
			txVuln.Modified = customTime
			txVuln.IsWithdrawn = isWithdrawn
			if _, err := tx.Put(dsVulnKey, &txVuln); err != nil {
				return err
			}

			if updateListed {
				listedKey := datastore.NameKey("ListedVulnerability", id, nil)
				if isWithdrawn {
					if err := tx.Delete(listedKey); err != nil && !errors.Is(err, datastore.ErrNoSuchEntity) {
						return err
					}
				} else {
					if _, err := tx.Put(listedKey, newListed); err != nil {
						return err
					}
				}
			}

			return nil
		})
		if err != nil {
			return false, fmt.Errorf("failed to update Datastore entities for %s: %w", id, err)
		}

		return true, nil
	}

	return false, fmt.Errorf("exhausted retries mutating vulnerability %s", id)
}

func (s *VulnerabilityStore) writeBaseEntities(ctx context.Context, req models.WriteRequest) error {
	tx, err := s.client.NewTransaction(ctx)
	if err != nil {
		return fmt.Errorf("failed to start transaction: %w", err)
	}
	// Use a deferred rollback as a safety net for early returns or panics.
	// Discard error because it returns an error if transaction was already committed.
	defer func() {
		_ = tx.Rollback()
	}()

	dsVulnKey := datastore.NameKey("Vulnerability", req.ID, nil)
	dsVuln := new(Vulnerability)
	if err := tx.Get(dsVulnKey, dsVuln); err != nil && !errors.Is(err, datastore.ErrNoSuchEntity) {
		return fmt.Errorf("failed to get old Vulnerability: %w", err)
	}

	dsVuln.SourceID = req.Source + ":" + req.Path
	dsVuln.Modified = req.Enriched.GetModified().AsTime()
	dsVuln.IsWithdrawn = req.Enriched.GetWithdrawn() != nil

	if req.Raw != nil {
		dsVuln.ModifiedRaw = req.Raw.GetModified().AsTime()
		dsVuln.AliasRaw = req.Raw.GetAliases()
		dsVuln.RelatedRaw = req.Raw.GetRelated()
		dsVuln.UpstreamRaw = req.Raw.GetUpstream()
	}

	listedVulnKey := datastore.NameKey("ListedVulnerability", req.ID, nil)
	listedVuln := NewListedVulnerabilityFromProto(req.Enriched)

	if dsVuln.IsWithdrawn {
		if _, err := tx.Put(dsVulnKey, dsVuln); err != nil {
			return fmt.Errorf("failed to put Vulnerability: %w", err)
		}
		if err := tx.Delete(listedVulnKey); err != nil && !errors.Is(err, datastore.ErrNoSuchEntity) {
			return fmt.Errorf("failed to delete ListedVulnerability: %w", err)
		}
	} else {
		if _, err := tx.Put(dsVulnKey, dsVuln); err != nil {
			return fmt.Errorf("failed to put Vulnerability: %w", err)
		}
		if _, err := tx.Put(listedVulnKey, listedVuln); err != nil {
			return fmt.Errorf("failed to put ListedVulnerability: %w", err)
		}
	}

	if err := s.updateAffectedVersions(ctx, tx, dsVuln.IsWithdrawn, req.Enriched); err != nil {
		return err
	}

	if _, err := tx.Commit(); err != nil {
		return fmt.Errorf("failed to commit transaction: %w", err)
	}

	return nil
}

func (s *VulnerabilityStore) updateAffectedVersions(ctx context.Context, tx *datastore.Transaction, isWithdrawn bool, enriched *osvschema.Vulnerability) error {
	var oldAffected []AffectedVersions
	q := datastore.NewQuery("AffectedVersions").FilterField("vuln_id", "=", enriched.GetId()).Transaction(tx)
	keys, err := s.client.GetAll(ctx, q, &oldAffected)
	if err != nil {
		return fmt.Errorf("failed to query old AffectedVersions: %w", err)
	}

	if isWithdrawn {
		for _, k := range keys {
			if err := tx.Delete(k); err != nil && !errors.Is(err, datastore.ErrNoSuchEntity) {
				return fmt.Errorf("failed to delete old AffectedVersions: %w", err)
			}
		}
	} else {
		newAffected := computeAffectedVersions(enriched)

		oldKeysMap := make(map[string]*datastore.Key)
		for i, av := range oldAffected {
			oldKeysMap[av.sortKey()] = keys[i]
		}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("failed to commit transaction for %s: %w", id, err)
	}

	return nil
}

// Write atomically updates the base record and its derived indexes.
func (s *VulnerabilityStore) Write(ctx context.Context, req models.WriteRequest) error {
	if req.Enriched == nil {
		return errors.New("enriched vulnerability is required")
	}
	id := cmp.Or(req.ID, req.Enriched.GetId())
	if id == "" {
		return errors.New("vulnerability ID is required")
	}

	enrichedProto, err := proto.MarshalOptions{Deterministic: true}.Marshal(req.Enriched)
	if err != nil {
		return fmt.Errorf("failed to marshal enriched proto for %s: %w", id, err)
	}
	enrichedJSON, err := marshalVulnJSON(req.Enriched)
	if err != nil {
		return fmt.Errorf("failed to marshal enriched JSON for %s: %w", id, err)
	}

	var rawJSON, rawSHA256 []byte
	if req.Raw != nil {
		if len(req.RawJSON) > 0 {
			rawJSON = schema.SanitizeJSON(req.RawJSON)
		} else if rawJSON, err = marshalVulnJSON(req.Raw); err != nil {
			return fmt.Errorf("failed to marshal raw JSON for %s: %w", id, err)
		}

		rawSHA256 = req.RawSHA256
		if len(rawSHA256) == 0 {
			sum := sha256.Sum256(rawJSON)
			rawSHA256 = sum[:]
		}
	}

	affectedVersions, err := ComputeAffectedVersions(req.Enriched)
	if err != nil {
		return fmt.Errorf("failed to compute affected versions for %s: %w", id, err)
	}

	var sortedCommits [][]byte
	if !req.AffectedCommits.Skip && req.Enriched.GetWithdrawn() == nil && len(req.AffectedCommits.Commits) > 0 {
		sortedCommits = slices.Clone(req.AffectedCommits.Commits)
		slices.SortFunc(sortedCommits, bytes.Compare)
		sortedCommits = slices.CompactFunc(sortedCommits, bytes.Equal)
	}

	return s.withTx(ctx, id, func(q *Queries) error {
		params := UpsertVulnerabilityParams{
			ID:         id,
			SourceID:   req.Source,
			SourcePath: req.Path,
			Modified:   req.Enriched.GetModified().AsTime().UTC(),
			Withdrawn:  pbTimePtr(req.Enriched.GetWithdrawn()),
			Data:       enrichedJSON,
			Proto:      enrichedProto,
			HasRaw:     req.Raw != nil,
		}
		if req.Raw != nil {
			rawID, err := writeRawVulnerability(ctx, q, id, req, rawJSON, rawSHA256)
			if err != nil {
				return err
			}
			params.RawVulnID = &rawID
			params.SourceModified = pbTimePtr(req.Raw.GetModified())
			params.AliasRaw = req.Raw.GetAliases()
			params.RelatedRaw = req.Raw.GetRelated()
			params.UpstreamRaw = req.Raw.GetUpstream()
		}

		if err := q.UpsertVulnerability(ctx, params); err != nil {
			return fmt.Errorf("failed to upsert vulnerabilities for %s: %w", id, err)
		}
		if err := updateAffectedVersions(ctx, q, id, affectedVersions); err != nil {
			return err
		}

		return updateAffectedCommits(ctx, q, id, req.AffectedCommits.Skip, sortedCommits)
	})
}

func writeRawVulnerability(ctx context.Context, q *Queries, id string, req models.WriteRequest, rawJSON, rawSHA256 []byte) (int64, error) {
	fetchedAt := time.Now().UTC()
	if req.FetchedAt != nil && !req.FetchedAt.IsZero() {
		fetchedAt = req.FetchedAt.UTC()
	}
	var gitCommit *string
	if req.GitCommitHash != "" {
		gitCommit = &req.GitCommitHash
	}

	rawID, err := q.UpsertRawVulnerability(ctx, UpsertRawVulnerabilityParams{
		VulnID:        &id,
		SourceID:      req.Source,
		SourcePath:    req.Path,
		ContentSha256: rawSHA256,
		GitCommitHash: gitCommit,
		GcsGeneration: req.GCSGeneration,
		RawData:       rawJSON,
		FetchedAt:     fetchedAt,
	})
	if err != nil {
		return 0, fmt.Errorf("failed to upsert raw_vulnerabilities for %s: %w", id, err)
	}

	return rawID, nil
}

func updateAffectedCommits(ctx context.Context, q *Queries, id string, skip bool, sortedCommits [][]byte) error {
	if skip {
		return nil
	}
	if len(sortedCommits) == 0 {
		if err := q.ClearAffectedCommits(ctx, id); err != nil {
			return fmt.Errorf("failed to clear affected_commits for %s: %w", id, err)
		}

		return nil
	}
	if err := q.SyncAffectedCommits(ctx, SyncAffectedCommitsParams{
		VulnID:  id,
		Commits: sortedCommits,
	}); err != nil {
		return fmt.Errorf("failed to sync affected_commits for %s: %w", id, err)
	}

	return nil
}

func updateAffectedVersions(ctx context.Context, q *Queries, id string, newAffected []AffectedVersionRow) error {
	if len(newAffected) == 0 {
		if err := q.DeleteAffectedVersionsByVulnID(ctx, id); err != nil {
			return fmt.Errorf("failed to delete old affected_versions for %s: %w", id, err)
		}

		return nil
	}

	oldAffected, err := q.ListAffectedVersionsByVulnID(ctx, id)
	if err != nil {
		return fmt.Errorf("failed to list old affected_versions for %s: %w", id, err)
	}

	var removedIDs []int64
	oldKeysMap := make(map[string]int64, len(oldAffected))
	for _, oav := range oldAffected {
		key := oav.sortKey()
		if _, exists := oldKeysMap[key]; exists {
			removedIDs = append(removedIDs, oav.ID)
			continue
		}
		oldKeysMap[key] = oav.ID
	}

	newKeys := make(map[string]bool, len(newAffected))
	var added []InsertAffectedVersionsParams
	for _, nav := range newAffected {
		key := nav.sortKey()
		if newKeys[key] {
			continue
		}
		newKeys[key] = true
		if _, exists := oldKeysMap[key]; !exists {
			added = append(added, InsertAffectedVersionsParams{
				VulnID:        nav.VulnID,
				Name:          nav.Name,
				BaseEcosystem: nav.BaseEcosystem,
				Ecosystems:    nav.Ecosystems,
				CoarseMin:     nav.CoarseMin,
				CoarseMax:     nav.CoarseMax,
				Versions:      nav.Versions,
				Events:        nav.EventsJSON,
			})
		}
	}

	for key, rowID := range oldKeysMap {
		if !newKeys[key] {
			removedIDs = append(removedIDs, rowID)
		}
	}

	if len(removedIDs) > 0 {
		if err := q.DeleteAffectedVersionsByIDs(ctx, removedIDs); err != nil {
			return fmt.Errorf("failed to delete removed affected_versions for %s: %w", id, err)
		}
	}

	if len(added) > 0 {
		br := q.InsertAffectedVersions(ctx, added)
		var batchErr error
		br.Exec(func(_ int, err error) {
			if err != nil && batchErr == nil {
				batchErr = err
			}
		})
		if batchErr != nil {
			return fmt.Errorf("failed to insert affected_versions for %s: %w", id, batchErr)
		}
	}

	return nil
}

// Mutate atomically reads the vulnerability, applies mutateFn, and persists the record if modified=true.
func (s *VulnerabilityStore) Mutate(ctx context.Context, id string, mutateFn models.MutateFunc) (bool, error) {
	if !isValidPGText(id) {
		return false, models.ErrNotFound
