// Package purl implements an enricher that adds missing PURLs to affected packages, and cleans up some invalid PURLs.
package purl

import (
	"context"
	"log/slog"

	"github.com/google/osv.dev/go/internal/worker/pipeline"
	"github.com/google/osv.dev/go/logger"
	"github.com/google/osv.dev/go/purl"
	"github.com/ossf/osv-schema/bindings/go/osvschema"
	packageurl "github.com/package-url/packageurl-go"
)

type Enricher struct{}

var _ pipeline.Enricher = (*Enricher)(nil)

func (*Enricher) Enrich(ctx context.Context, vuln *osvschema.Vulnerability, _ *pipeline.EnrichParams) error {
	for _, affected := range vuln.GetAffected() {
		pkg := affected.GetPackage()
		if purlStr := pkg.GetPurl(); purlStr != "" {
			pkgPURL, err := packageurl.FromString(purlStr)
			if err == nil {
				if pkgPURL.Version != "" {
					logger.WarnContext(ctx, "package has purl with version, stripping",
						slog.String("purl", purlStr),
						slog.String("vuln_id", vuln.GetId()),
						slog.String("ecosystem", pkg.GetEcosystem()),
						slog.String("name", pkg.GetName()),
					)
					pkgPURL.Version = ""
					pkg.Purl = pkgPURL.ToString()
				}
				// PURL is valid, nothing to do.
				continue
			}

			// PURL is invalid, discard it
			logger.ErrorContext(ctx, "package has invalid purl, discarding",
				slog.String("purl", purlStr),
				slog.String("vuln_id", vuln.GetId()),
				slog.String("ecosystem", pkg.GetEcosystem()),
				slog.String("name", pkg.GetName()),
				slog.Any("error", err),
			)
			pkg.Purl = ""
		}

		// We require an ecosystem and a name to form a PURL
		if pkg.GetEcosystem() == "" || pkg.GetName() == "" {
			continue
		}

		purlStr, err := purl.Generate(pkg.GetEcosystem(), pkg.GetName())
		if err != nil {
			logger.WarnContext(ctx, "failed to generate purl",
				slog.String("vuln_id", vuln.GetId()),
				slog.String("ecosystem", pkg.GetEcosystem()),
				slog.String("name", pkg.GetName()),
				slog.Any("error", err),
			)

			continue
		}
		pkg.Purl = purlStr
	}

	return nil
}
// Package namenormalize implements an enricher that normalizes package names in a vulnerability.
package namenormalize

import (
	"context"
	"log/slog"

	"github.com/google/osv.dev/go/internal/worker/pipeline"
	"github.com/google/osv.dev/go/logger"
	"github.com/google/osv.dev/go/osv/ecosystem"
	"github.com/ossf/osv-schema/bindings/go/osvschema"
)

type Enricher struct{}

var _ pipeline.Enricher = (*Enricher)(nil)

func (*Enricher) Enrich(ctx context.Context, vuln *osvschema.Vulnerability, params *pipeline.EnrichParams) error {
	provider := params.EcosystemProvider
	if provider == nil {
		logger.WarnContext(ctx, "ecosystem provider is nil, using default", slog.String("vuln_id", vuln.GetId()))
		provider = ecosystem.DefaultProvider
	}
	for _, affected := range vuln.GetAffected() {
		pkg := affected.GetPackage()
		ecosystemName := pkg.GetEcosystem()
		if ecosystemName == "" {
			continue
		}
		sys, ok := provider.Get(ecosystemName)
		if !ok {
			// Ecosystem not found - other enrichers can log better warnings about this.
			continue
		}
		pkg.Name = ecosystem.NormalizePackageName(sys, pkg.GetName())
	}

	return nil
}
// Package filterecosystem implements an enricher that filters out affected ecosystems that should not be there.
package filterecosystem

import (
	"context"
	"log/slog"
	"slices"
	"strings"

	"github.com/google/osv.dev/go/internal/osvutil/schema"
	"github.com/google/osv.dev/go/internal/worker/pipeline"
	"github.com/google/osv.dev/go/logger"
	"github.com/ossf/osv-schema/bindings/go/osvconstants"
	"github.com/ossf/osv-schema/bindings/go/osvschema"
	"google.golang.org/protobuf/proto"
)

type Enricher struct{}

var _ pipeline.Enricher = (*Enricher)(nil)

func (*Enricher) Enrich(ctx context.Context, vuln *osvschema.Vulnerability, params *pipeline.EnrichParams) error {
	newAffected := make([]*osvschema.Affected, 0, len(vuln.GetAffected()))
	acceptedEcos := params.SourceRepo.AcceptedEcosystems
	allowAll := slices.Contains(acceptedEcos, "*")
	for _, affected := range vuln.GetAffected() {
		pkg := affected.GetPackage()
		if pkg == nil {
			// If there is already no affected package, assume this is a GIT vuln and add it anyway.
			newAffected = append(newAffected, proto.Clone(affected).(*osvschema.Affected))
			continue
		}
		ecosystem := pkg.GetEcosystem()
