	registerSimple(osvconstants.EcosystemAlpine, "apk", "alpine", sourceArchQualifiers)
	registerSimple(osvconstants.EcosystemBellSoftHardenedContainers, "apk", "bellsoft-hardened-containers", sourceArchQualifiers)

