						slog.String("vuln_id", vuln.GetId()),
						slog.String("ecosystem", ecosystemName),
						slog.String("event_value", eventValue))
					isValidSemverRange = false

					break
				}
			}
			if isValidSemverRange {
				r.Type = osvschema.Range_SEMVER
			}
		}
	}

	return nil
}

