func parseMatchCommitsCursor(cursor string) (*matchCommitsCursor, error) {
	remaining, ok := strings.CutPrefix(cursor, matchCommitCursorPrefix)
	if !ok {
		return nil, errors.New("cursor not in correct format")
	}
	parsedCursor, err := datastore.DecodeCursor(remaining)
	if err != nil {
		return nil, err
	}

	return &matchCommitsCursor{cursor: parsedCursor}, nil
}

func (s *VulnerabilityStore) MatchCommits(ctx context.Context, commit []byte, cursor string) iter.Seq2[models.MatchResult, error] {
	return func(yield func(models.MatchResult, error) bool) {
		q := datastore.NewQuery("AffectedCommits").
			FilterField("commits", "=", commit).
			FilterField("public", "=", true).
			KeysOnly()
		if cursor != "" {
			parsedCursor, err := parseMatchCommitsCursor(cursor)
			if err != nil {
				yield(models.MatchResult{}, fmt.Errorf("%w: %w", models.ErrInvalidCursor, err))
				return
			}
			q = q.Start(parsedCursor.cursor)
		}

		it := s.client.Run(ctx, q)

		yieldWithCursor := func(match bool, id string) bool {
			cursor, err := it.Cursor()
			if err != nil {
				yield(models.MatchResult{}, fmt.Errorf("failed to get cursor: %w", err))
				return false
			}

			return yield(models.MatchResult{IsMatch: match, ID: id, Cursor: matchCommitsCursor{cursor: cursor}.String}, nil)
		}
		for {
			k, err := it.Next(nil)
			if errors.Is(err, iterator.Done) {
				return
			}
			if err != nil {
				if st, ok := status.FromError(err); ok && st.Code() == codes.InvalidArgument {
					// An InvalidArgument error usually means the cursor is malformed.
					yield(models.MatchResult{}, fmt.Errorf("%w: %w", models.ErrInvalidCursor, err))
					return
				}
				yield(models.MatchResult{}, fmt.Errorf("failed to fetch affected commits: %w", err))

				return
			}

			idx := strings.LastIndex(k.Name, "-")
			if idx == -1 {
				logger.WarnContext(ctx, "Invalid affected commits key", slog.String("key", k.Name))
				if !yieldWithCursor(false, "") {
					return
				}

				continue
			}
			vulnID := k.Name[:idx]

			// TODO(michaelkedar): very inefficient, but necessary for now to filter out withdrawn vulns
			// Add a `is_withdrawn` field to AffectedCommits to avoid this read
			vulnKey := datastore.NameKey("Vulnerability", vulnID, nil)
			var vuln Vulnerability
			if err := s.client.Get(ctx, vulnKey, &vuln); err != nil {
				if errors.Is(err, datastore.ErrNoSuchEntity) {
					// This means we have a reference to a vulnerability that doesn't exist.
					logger.WarnContext(ctx, "AffectedCommits points to a nonexistent vulnerability", slog.String("vuln_id", vulnID))
					if !yieldWithCursor(false, "") {
						return
					}

					continue
				}
				yield(models.MatchResult{}, fmt.Errorf("failed to fetch withdrawn information: %w", err))

				return
			}
			if vuln.IsWithdrawn {
				if !yieldWithCursor(false, "") {
					return
				}

				continue
			}
			if !yieldWithCursor(true, vulnID) {
				return
			}
		}
	}
}

