// matchPackagesCursor represents the keyset pagination position (afterVulnID, afterRowID)
// in affected_versions ordered by (vuln_id, id).
//
// Once a vuln_id has been matched, afterRowID is set to math.MaxInt64 so that:
//  1. Any remaining rows for the same vuln_id in the current in-memory page are skipped.
//  2. Resuming from the cursor in SQL via `WHERE (vuln_id, id) > (@after_vuln_id, @after_row_id)`
//     skips all remaining rows for afterVulnID in the index and jumps directly to the next vuln_id.
type matchPackagesCursor struct {
	afterVulnID string
	afterRowID  int64
}

func (c matchPackagesCursor) String() string {
	// Since Postgres IDENTITY row IDs are always >= 1, we encode math.MaxInt64 as 0
	// on the wire so it takes 1 byte in varint encoding instead of 10 bytes.
	wireRowID := c.afterRowID
	if wireRowID == math.MaxInt64 {
		wireRowID = 0
	}
	buf := make([]byte, 0, 1+binary.MaxVarintLen64+len(c.afterVulnID))
	buf = append(buf, cursorTypePackage)
	buf = binary.AppendVarint(buf, wireRowID)
	buf = append(buf, c.afterVulnID...)

	return base64.RawURLEncoding.EncodeToString(buf)
}

func parseMatchPackagesCursor(cursor string) (matchPackagesCursor, error) {
	b, err := base64.RawURLEncoding.DecodeString(cursor)
	if err != nil {
		return matchPackagesCursor{}, err
	}
	if len(b) < 2 || b[0] != cursorTypePackage {
		return matchPackagesCursor{}, errors.New("cursor not in correct format")
	}

	wireRowID, n := binary.Varint(b[1:])
	if n <= 0 || wireRowID < 0 {
		return matchPackagesCursor{}, errors.New("cursor not in correct format")
	}
	afterRowID := wireRowID
	if afterRowID == 0 {
		afterRowID = math.MaxInt64
	}
	afterVulnID := string(b[1+n:])
	if !isValidPGText(afterVulnID) {
		return matchPackagesCursor{}, errors.New("cursor not in correct format")
	}

	return matchPackagesCursor{
		afterVulnID: afterVulnID,
		afterRowID:  afterRowID,
	}, nil
}

