				SourceRepository: sourceRepo.Name,
				SourcePath:       from,
				Action:           ActionWithdraw,
				Strict:           sourceRepo.Strictness,
				Format:           format,
				KeyPath:          sourceRepo.KeyPath,
				IsReimport:       isReimport,
				WorkPool:         pool,
			}:
