			IDPrefixes:       sourceRepo.IDPrefixes,
			Format:           format,
			KeyPath:          sourceRepo.KeyPath,
			IsReimport:       isReimport,
			Strict:           sourceRepo.Strictness,
			WorkPool:         pool,
		}:
