func (s *VulnerabilityStore) updateAffectedCommits(ctx context.Context, id string, commits [][]byte) error {
	// Write batched commit indexes.
	// Sort the commits for some determinism.
	sortedCommits := slices.Clone(commits)
	slices.SortFunc(sortedCommits, bytes.Compare)

	var toPut []*AffectedCommits
	var keys []*datastore.Key
	numPages := 0
	const batchSize = 10000
	for i := 0; i < len(sortedCommits); i += batchSize {
		end := min(i+batchSize, len(sortedCommits))
		batch := sortedCommits[i:end]

		acKey := datastore.NameKey("AffectedCommits", fmt.Sprintf("%s-%d", id, numPages), nil)
		ac := &AffectedCommits{
			VulnID:  id,
			Commits: batch,
			Public:  true,
			Page:    numPages,
		}
		toPut = append(toPut, ac)
		keys = append(keys, acKey)
		numPages++
	}

	// If there are too many, AffectedCommits is too big for a single batch put
	// So just put them one-by-one
	for i, ac := range toPut {
		if _, err := s.client.Put(ctx, keys[i], ac); err != nil {
			return fmt.Errorf("failed to write AffectedCommits: %w", err)
		}
	}

	// Clear any previously written that we didn't just write.
	q := datastore.NewQuery("AffectedCommits").FilterField("bug_id", "=", id).KeysOnly()
	keys, err := s.client.GetAll(ctx, q, nil)
	if err != nil {
		return fmt.Errorf("failed to query AffectedCommits: %w", err)
	}

	for _, k := range keys {
		parts := strings.Split(k.Name, "-")
		page, err := strconv.Atoi(parts[len(parts)-1])
		if err != nil {
			return fmt.Errorf("failed to parse page number from key: %w", err)
		}
		if page >= numPages {
			if err := s.client.Delete(ctx, k); err != nil {
				return fmt.Errorf("failed to delete AffectedCommits: %w", err)
			}
		}
	}

	return nil
}

func (s *VulnerabilityStore) uploadToGCS(ctx context.Context, id string, enriched *osvschema.Vulnerability) error {
	path := fmt.Sprintf("all/pb/%s.pb", id)
	newData, err := proto.Marshal(enriched)
	if err != nil {
		return fmt.Errorf("failed to marshal enriched vulnerability: %w", err)
	}

	customTime := enriched.GetModified().AsTime()
	opts := &clients.WriteOptions{
		CustomTime: &customTime,
	}

	if err := s.gcsStore.WriteObject(ctx, path, newData, opts); err != nil {
		if s.failedWritePublisher == nil {
			// We don't have a recoverer, so we can't retry. Return the error.
			return fmt.Errorf("failed to write vulnerability object to GCS: %w", err)
		}
		// Try sending to recoverer to retry
		logger.ErrorContext(ctx, "failed to write vulnerability object to GCS, attempting to queue recovery task", slog.String("vuln_id", id), slog.Any("error", err))
		res := s.failedWritePublisher.Publish(ctx, &pubsub.Message{
			Data:       newData,
			Attributes: map[string]string{"type": "gcs_retry"},
		})
		if _, err := res.Get(ctx); err != nil {
			logger.ErrorContext(ctx, "failed to publish to failed write topic", slog.String("vuln_id", id), slog.Any("error", err))
			// If we failed to even try recover, propagate the error up to let the caller deal with this.
			return fmt.Errorf("failed to write vulnerability object to GCS: %w", err)
		}
		// Otherwise, sending to recoverer was successful, so we don't need to error anymore
	}

	return nil
}

